<script setup>
import {ref,computed,onMounted,onBeforeUnmount,nextTick} from 'vue';
import {state} from '../store';
import Icon from './Icon.vue';
const props=defineProps({file:{type:File,required:true}}),emit=defineEmits(['cancel','save']);
const copy=(en,id)=>state.language==='id'?id:en;
const dialog=ref(null),viewport=ref(null),image=ref(null),ready=ref(false),error=ref(''),saving=ref(false),zoom=ref(1),horizontal=ref(0),vertical=ref(0),size=ref(280);
let url='',observer,drag=null,disposed=false,decodingImage=null;
const geometry=computed(()=>{if(!image.value)return {width:0,height:0,scale:1,x:0,y:0};const scale=Math.max(size.value/image.value.naturalWidth,size.value/image.value.naturalHeight)*Number(zoom.value),width=image.value.naturalWidth*scale,height=image.value.naturalHeight*scale;return {scale,width,height,x:Number(horizontal.value)/100*(width-size.value)/2,y:Number(vertical.value)/100*(height-size.value)/2}});
const imageStyle=computed(()=>({width:geometry.value.width+'px',height:geometry.value.height+'px',left:`calc(50% + ${geometry.value.x}px)`,top:`calc(50% + ${geometry.value.y}px)`}));
function close(){if(!saving.value)emit('cancel')}
function pointerStart(event){if(!ready.value||event.button!==0)return;event.preventDefault();viewport.value.setPointerCapture(event.pointerId);drag={x:event.clientX,y:event.clientY,h:Number(horizontal.value),v:Number(vertical.value)};}
function pointerMove(event){if(!drag)return;const g=geometry.value,rangeX=(g.width-size.value)/2,rangeY=(g.height-size.value)/2;horizontal.value=rangeX?Math.max(-100,Math.min(100,drag.h+(event.clientX-drag.x)/rangeX*100)):0;vertical.value=rangeY?Math.max(-100,Math.min(100,drag.v+(event.clientY-drag.y)/rangeY*100)):0;}
async function save(){if(!ready.value||saving.value)return;saving.value=true;error.value='';try{const canvas=document.createElement('canvas');canvas.width=512;canvas.height=512;const context=canvas.getContext('2d');if(!context)throw new Error('Canvas unavailable');const g=geometry.value,sourceSize=size.value/g.scale,sourceX=((g.width-size.value)/2-g.x)/g.scale,sourceY=((g.height-size.value)/2-g.y)/g.scale;context.imageSmoothingEnabled=true;context.imageSmoothingQuality='high';context.beginPath();context.arc(256,256,256,0,Math.PI*2);context.clip();context.drawImage(image.value,sourceX,sourceY,sourceSize,sourceSize,0,0,512,512);const blob=await new Promise(resolve=>canvas.toBlob(resolve,'image/png'));if(!blob)throw new Error('Image conversion failed');if(!disposed)emit('save',new File([blob],'profile-photo.png',{type:'image/png'}));}catch{error.value=copy('The photo could not be cropped. Choose another image.','Foto tidak dapat dipotong. Pilih gambar lain.');saving.value=false}}
onMounted(async()=>{await nextTick();if(disposed||!dialog.value)return;dialog.value.showModal();url=URL.createObjectURL(props.file);const photo=new Image();decodingImage=photo;photo.onload=()=>{if(disposed)return;if(!photo.naturalWidth||!photo.naturalHeight||photo.naturalWidth*photo.naturalHeight>40000000){error.value=copy('Choose an image smaller than 40 megapixels.','Pilih gambar di bawah 40 megapiksel.');return}image.value=photo;ready.value=true;nextTick(()=>{if(disposed||!viewport.value)return;size.value=viewport.value.clientWidth;observer=new ResizeObserver(()=>{if(!disposed&&viewport.value)size.value=viewport.value.clientWidth});observer.observe(viewport.value)})};photo.onerror=()=>{if(!disposed)error.value=copy('This file is not a readable image. Choose a JPG, PNG or WebP photo.','File ini bukan gambar yang dapat dibaca. Pilih foto JPG, PNG, atau WebP.')};photo.src=url;});
onBeforeUnmount(()=>{disposed=true;observer?.disconnect();if(decodingImage){decodingImage.onload=null;decodingImage.onerror=null}if(url)URL.revokeObjectURL(url);if(dialog.value?.open)dialog.value.close()});
</script>

<template>
<Teleport to="body"><dialog ref="dialog" class="crop-dialog" aria-labelledby="crop-title" aria-describedby="crop-description" @cancel.prevent="close" @click="event=>{if(event.target===dialog)close()}">
 <div class="crop-heading"><div><h2 id="crop-title">{{copy('Crop your photo','Potong foto Anda')}}</h2><p id="crop-description">{{copy('Drag the photo or use the controls to frame your avatar.','Geser foto atau gunakan kontrol untuk mengatur avatar Anda.')}}</p></div><button class="icon-button" :disabled="saving" :aria-label="copy('Close photo crop','Tutup pemotongan foto')" @click="close"><Icon name="X"/></button></div>
 <div v-if="error" class="inline-error" role="alert">{{error}}</div>
 <div v-if="!ready&&!error" class="crop-loading" role="status"><span class="loader"></span>{{copy('Loading photo…','Memuat foto…')}}</div>
 <template v-if="ready"><div ref="viewport" class="crop-viewport" @pointerdown="pointerStart" @pointermove="pointerMove" @pointerup="drag=null" @pointercancel="drag=null" @lostpointercapture="drag=null"><img :src="url" :style="imageStyle" alt="" draggable="false"><span class="crop-guide"></span></div>
 <div class="crop-controls"><label for="avatar-zoom">{{copy('Zoom','Perbesar')}}<span>{{Number(zoom).toFixed(1)}}×</span></label><input id="avatar-zoom" v-model.number="zoom" type="range" min="1" max="3" step="0.05" :disabled="saving"><label for="avatar-horizontal">{{copy('Horizontal position','Posisi horizontal')}}</label><input id="avatar-horizontal" v-model.number="horizontal" type="range" min="-100" max="100" step="1" :disabled="saving"><label for="avatar-vertical">{{copy('Vertical position','Posisi vertikal')}}</label><input id="avatar-vertical" v-model.number="vertical" type="range" min="-100" max="100" step="1" :disabled="saving"></div></template>
 <div class="crop-footer"><button class="button secondary" :disabled="saving" @click="close">{{copy('Cancel','Batal')}}</button><button class="button crop-save" :disabled="!ready||saving" @click="save"><Icon name="Check" :size="18"/>{{saving?copy('Preparing…','Menyiapkan…'):copy('Use this photo','Gunakan foto ini')}}</button></div>
</dialog></Teleport>
</template>

<style scoped>
.crop-dialog{padding:1.5rem;border:1px solid var(--border);border-radius:1.25rem;background:var(--surface);color:var(--text);width:min(37rem,calc(100% - 2rem));max-height:calc(100dvh - 2rem);overflow:auto;box-shadow:var(--shadow);margin:auto;overscroll-behavior:contain}.crop-dialog::backdrop{background:color-mix(in srgb,var(--heading) 65%,transparent);backdrop-filter:blur(5px)}.crop-heading{display:flex;align-items:flex-start;gap:1rem;margin-bottom:1.5rem}.crop-heading>div{flex:1;min-width:0}.crop-heading p{margin-top:.5rem;color:var(--muted)}.crop-viewport{width:min(100%,18rem);aspect-ratio:1;margin:0 auto 1.5rem;overflow:hidden;position:relative;border-radius:50%;touch-action:none;background:var(--surface-alt);outline:3px solid var(--color-accent);cursor:grab;isolation:isolate}.crop-viewport:active{cursor:grabbing}.crop-viewport img{position:absolute;max-width:none;transform:translate(-50%,-50%);pointer-events:none;user-select:none}.crop-guide{position:absolute;inset:0;box-shadow:inset 0 0 0 1px #ffffff66;pointer-events:none;border-radius:50%}.crop-controls{display:grid;gap:.25rem}.crop-controls label{display:flex;justify-content:space-between;gap:1rem}.crop-controls input[type=range]{padding:0!important;min-height:44px;accent-color:var(--color-accent);box-shadow:none;border:0!important;background:transparent}.crop-controls input[type=range]:focus-visible{outline:3px solid var(--color-accent);outline-offset:2px}.crop-footer{display:flex;justify-content:flex-end;gap:.75rem;padding-top:1.25rem;margin-top:1rem;border-top:1px solid var(--border);flex-wrap:wrap}.crop-dialog .crop-save{background:var(--color-primary)!important;color:var(--color-primary-contrast,#092522)}.crop-loading{display:flex;align-items:center;gap:1rem;justify-content:center;min-height:12rem}@media(max-width:450px){.crop-dialog{padding:1rem}.crop-footer>.button{flex:1;min-width:0}.crop-heading{gap:.25rem}}
@media(max-width:450px){.crop-footer{flex-direction:column}.crop-footer>.button{width:100%;flex:none}}

.crop-heading h2{font-size:1.5rem;line-height:1.4;overflow-wrap:anywhere}.crop-heading p{font-size:1.125rem;line-height:1.7}.crop-heading>.icon-button{width:44px;height:44px}.crop-controls label{font-size:1.125rem;line-height:1.6;flex-wrap:wrap}.crop-controls input[type=range]{min-width:0;width:100%;min-height:48px}.crop-footer{position:sticky;bottom:-1.5rem;background:var(--surface);padding-bottom:1.5rem;margin-bottom:-1.5rem;z-index:1}.crop-footer>.button{white-space:normal;min-height:48px;font-size:1.0625rem;line-height:1.5;max-width:100%}.crop-loading{font-size:1.125rem}.crop-dialog :is(button,input):focus-visible{outline:3px solid var(--color-accent);outline-offset:3px}
@media(max-width:450px){.crop-footer{bottom:-1rem;padding-bottom:1rem;margin-bottom:-1rem}}
</style>
